describe('Username Pre-fill on Login', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should pre-fill username if previously logged in', () => {
    // Intercept login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');

    // Navigate to login page
    cy.get('[data-testid="username-input"]').should('be.visible');
    cy.get('[data-testid="password-input"]').should('be.visible');
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify username input is empty initially
    cy.get('[data-testid="username-input"]').should('have.value', '');

    // Simulate user logging in with stored credentials
    cy.get('[data-testid="username-input"]').type('testuser@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();

    // Wait for login API call
    cy.wait('@loginRequest');

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome, testuser@example.com');

    // Verify username was pre-filled
    cy.get('[data-testid="username-input"]').should('have.value', 'testuser@example.com');
  });

  it('should not pre-fill username if no previous login exists', () => {
    // Clear any local storage or cookies to simulate first-time user
    cy.clearCookies();
    cy.clearLocalStorage();

    // Navigate to login page
    cy.visit('/login');

    // Verify username input is empty
    cy.get('[data-testid="username-input"]').should('have.value', '');

    // Verify password input is empty
    cy.get('[data-testid="password-input"]').should('have.value', '');

    // Attempt to log in with valid credentials
    cy.get('[data-testid="username-input"]').type('newuser@example.com');
    cy.get('[data-testid="password-input"]').type('SecurePassword123!');
    cy.get('[data-testid="login-button"]').click();

    // Wait for login API call
    cy.intercept('POST', '/api/auth/login').as('loginRequest');
    cy.wait('@loginRequest');

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');

    // Verify username was not pre-filled
    cy.get('[data-testid="username-input"]').should('have.value', 'newuser@example.com');
  });
});
